from taf.internal.managedobject import ManagedObject
from taf.transport.ssh.connection import SSHConnection
from taf.transport.ssh import ssh


class SshConnection(ManagedObject, SSHConnection):
    def __init__(self, ip_addr, user, password, port=None, *args, **kwargs):
        super(SshConnection, self).__init__(*args, **kwargs)
        self.__ip_addr = ip_addr
        self.__user = user
        self.__password = password
        self.__port = port
        self.configure(hostname=self.__ip_addr, username=self.__user,
                       password=self.__password, port=self.__port)

    def _setup(self):
        self.connect()

    def _teardown(self):
        self.disconnect()


ssh = ssh()


def managed_from_aliased(alias):
    def _setup(self):
        if not self.is_connected:
            self.connect()

    def _teardown(self):
        if self.is_connected:
            self.disconnect()

    managed_obj = ManagedObject()
    connection = ssh.get_connection_by_alias(alias)
    _merge_objects(connection, managed_obj)
    connection._setup = _setup
    connection._teardown = _teardown
    connection.is_up = False
    connection.setup = managed_obj.setup
    connection.teardown = managed_obj.teardown
    return connection


def _merge_objects(a, b):
    a.__dict__.update(b.__dict__)
